package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Explicit two-stage hierarchical component models; no frozen-score bootstrap. */
public final class HigherOrderPls {
    private HigherOrderPls(){}
    public record Dimension(String name,int[] lowerOrder,PlsSem.Mode mode,PlsSem.MeasurementType measurementType,double[] initialWeights){
        public Dimension {Objects.requireNonNull(name);Objects.requireNonNull(mode);Objects.requireNonNull(measurementType);lowerOrder=lowerOrder.clone();
            if(name.isBlank()||lowerOrder.length<2||Arrays.stream(lowerOrder).distinct().count()!=lowerOrder.length||Arrays.stream(lowerOrder).anyMatch(value->value<0))throw new IllegalArgumentException("Name each higher-order construct and choose at least two distinct lower-order dimensions.");
            if(initialWeights==null){initialWeights=new double[lowerOrder.length];Arrays.fill(initialWeights,1);}else initialWeights=initialWeights.clone();
            if(initialWeights.length!=lowerOrder.length||Arrays.stream(initialWeights).anyMatch(value->!Double.isFinite(value))||Arrays.stream(initialWeights).allMatch(value->value==0))throw new IllegalArgumentException("Use a finite, nonzero initial weight vector matching the lower-order dimensions.");}
        @Override public int[] lowerOrder(){return lowerOrder.clone();}@Override public double[] initialWeights(){return initialWeights.clone();}
    }
    public record Specification(int[] retained,List<Dimension> higherOrder,List<PlsSem.Edge> edges,PlsSem.Options options){
        public Specification {retained=retained.clone();higherOrder=List.copyOf(higherOrder);edges=List.copyOf(edges);Objects.requireNonNull(options);
            if(higherOrder.isEmpty()||higherOrder.size()+retained.length>64||Arrays.stream(retained).distinct().count()!=retained.length||Arrays.stream(retained).anyMatch(value->value<0))throw new IllegalArgumentException("Choose higher-order definitions and unique retained constructs, with at most 64 stage-two constructs.");}
        @Override public int[] retained(){return retained.clone();}
    }
    public record DimensionResult(int higherOrder,String name,int lowerOrder,String dimension,PlsSem.Mode mode,PlsSem.MeasurementType measurementType,double weight,double loading){}
    public record Effect(String family,int source,int target,double value){}
    public record SpecificIndirect(int source,int target,List<Integer> route,double value){public SpecificIndirect{route=List.copyOf(route);}}
    public record Fit(Specification specification,PlsSem.Options firstStageOptions,int observations,int originalColumns,
                      List<PlsSem.Block> firstStageBlocks,List<PlsSem.Edge> firstStageEdges,List<PlsSem.Block> secondStageBlocks,
                      PlsSem.Fit firstStage,PlsSem.Fit secondStage,List<DimensionResult> dimensions,List<Effect> effects,List<SpecificIndirect> specificIndirect,List<String> warnings){
        public Fit {firstStageBlocks=List.copyOf(firstStageBlocks);firstStageEdges=List.copyOf(firstStageEdges);secondStageBlocks=List.copyOf(secondStageBlocks);dimensions=List.copyOf(dimensions);effects=List.copyOf(effects);specificIndirect=List.copyOf(specificIndirect);warnings=List.copyOf(warnings);
            if(observations<3||originalColumns<1||firstStage.scores().length!=observations||secondStage.scores().length!=observations||!firstStage.converged()||!secondStage.converged())throw new IllegalArgumentException("Invalid or unconverged higher-order result.");}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    private record Prepared(List<PlsSem.Block> blocks,List<String> warnings,List<List<Integer>> routes,List<Bootstrap.Parameter> parameters){}
    private record State(Fit result,double[] base,double[][] augmented){}
    private static void dag(int count,List<PlsSem.Edge> edges){boolean[][] graph=new boolean[count][count];int[] degree=new int[count];for(var edge:edges){if(edge.source()<0||edge.target()<0||edge.source()>=count||edge.target()>=count||edge.source()==edge.target()||graph[edge.source()][edge.target()])throw new IllegalArgumentException("Invalid or duplicate higher-order stage connection.");graph[edge.source()][edge.target()]=true;degree[edge.target()]++;}ArrayDeque<Integer> pending=new ArrayDeque<>();for(int j=0;j<count;j++)if(degree[j]==0)pending.add(j);int visited=0;while(!pending.isEmpty()){int source=pending.remove();visited++;for(int target=0;target<count;target++)if(graph[source][target]&&--degree[target]==0)pending.add(target);}if(visited!=count)throw new IllegalArgumentException("Each higher-order stage must be acyclic.");}
    private static Prepared prepare(int width,List<PlsSem.Block> first,List<PlsSem.Edge> firstEdges,Specification specification){
        if(width<1||first.size()<2||first.size()>64)throw new IllegalArgumentException("Provide 2–64 measured first-stage constructs.");dag(first.size(),firstEdges);List<String> warnings=new ArrayList<>();Set<String> names=new HashSet<>();for(var block:first){if(block.name().isBlank()||!names.add(block.name()))throw new IllegalArgumentException("First-stage construct names must be unique.");for(int column:block.columns())if(column<0||column>=width)throw new IllegalArgumentException("First-stage indicator out of range.");}
        Set<Integer> sourceIndicators=new HashSet<>();boolean shared=false;for(var block:first)for(int column:block.columns())if(!sourceIndicators.add(column))shared=true;if(shared)warnings.add("The declared first-stage model contains shared/repeated indicators. With an explicit first-stage HOC and its LOC measurement relationships this is an embedded two-stage specification. The complete first-stage graph is refitted, including those relationships; inspect the declared measurement graph rather than interpreting this as an automatically disjoint first stage.");
        Set<Integer> consumed=new HashSet<>();for(var dimension:specification.higherOrder){if(!names.add(dimension.name))throw new IllegalArgumentException("Give each higher-order construct a new unique name.");for(int lower:dimension.lowerOrder){if(lower>=first.size())throw new IllegalArgumentException("Lower-order dimension out of range.");if(!consumed.add(lower))warnings.add(first.get(lower).name()+": dimension reused across higher-order constructs; examine overlap and collinearity.");}}
        List<PlsSem.Block> second=new ArrayList<>();Set<Integer> retained=new HashSet<>();for(int index:specification.retained){if(index>=first.size()||consumed.contains(index))throw new IllegalArgumentException("Two-stage score models cannot retain a consumed lower-order construct as a separate stage-two construct.");retained.add(index);second.add(first.get(index));}
        for(var dimension:specification.higherOrder){int[] columns=Arrays.stream(dimension.lowerOrder).map(index->width+index).toArray();second.add(new PlsSem.Block(dimension.name,columns,dimension.mode,dimension.initialWeights,dimension.measurementType));}
        dag(second.size(),specification.edges);for(int j=0;j<first.size();j++)if(!consumed.contains(j)&&!retained.contains(j))warnings.add(first.get(j).name()+": present in stage one but omitted from stage two by the explicit specification.");
        for(int stage=0;stage<2;stage++){var blocks=stage==0?first:second;var edges=stage==0?firstEdges:specification.edges;boolean[] connected=new boolean[blocks.size()];for(var edge:edges){connected[edge.source()]=true;connected[edge.target()]=true;}for(int j=0;j<blocks.size();j++)if(!connected[j]&&blocks.get(j).mode()==PlsSem.Mode.B)warnings.add("Stage "+(stage+1)+" "+blocks.get(j).name()+": isolated Mode B weights retain their initial composite definition and are not identified by structural neighbors.");}
        warnings.add("Explicit two-stage composite PLS, not higher-order covariance-factor ML or PLSc. Specify theoretically appropriate first-stage main effects and second-stage relationships.");
        warnings.add("Consumed lower-order constructs become stage-two score indicators; retained constructs keep their original raw indicators. Measurement type and weight mode are recorded separately.");
        warnings.add("Higher-order dimension relationships are interpreted as loadings for reflective measurement and weights for formative measurement, not ordinary structural paths.");
        warnings.add("Full-procedure IID bootstrap refits both stages and aligns score orientation at both levels. Resampling does not establish construct validity or causality.");
        return new Prepared(List.copyOf(second),List.copyOf(warnings),routes(second.size(),specification.edges),Bootstrap.parameters(second,specification.edges));
    }
    private static List<List<Integer>> routes(int count,List<PlsSem.Edge> edges){List<List<Integer>> result=new ArrayList<>();for(int source=0;source<count;source++)walk(source,new ArrayList<>(List.of(source)),edges,result);return List.copyOf(result);}
    private static void walk(int current,List<Integer> path,List<PlsSem.Edge> edges,List<List<Integer>> output){for(var edge:edges)if(edge.source()==current){var next=new ArrayList<>(path);next.add(edge.target());if(next.size()>2){output.add(List.copyOf(next));if(output.size()>10000)throw new IllegalArgumentException("More than 10,000 specific indirect routes; simplify stage two.");}walk(edge.target(),next,edges,output);}}
    public static void validate(int width,List<PlsSem.Block> first,List<PlsSem.Edge> edges,Specification specification){prepare(width,first,edges,specification);}
    public static List<PlsSem.Block> stageTwoBlocks(int width,List<PlsSem.Block> first,List<PlsSem.Edge> edges,Specification specification){return prepare(width,first,edges,specification).blocks;}
    public static double[][] augment(double[][] data,double[][] scores){int width=Matrices.width(data,3);if(scores.length!=data.length||Matrices.width(scores,3)>64||(long)data.length*(width+scores[0].length)>5000000L)throw new IllegalArgumentException("Higher-order augmented data differ in rows or exceed five million cells.");double[][] result=new double[data.length][width+scores[0].length];for(int i=0;i<data.length;i++){Matrices.interrupted();System.arraycopy(data[i],0,result[i],0,width);System.arraycopy(scores[i],0,result[i],width,scores[i].length);}return result;}
    private static State compute(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Specification specification,Prepared prepared,double[][] referenceOne,double[][] referenceTwo,int[] rows){
        Matrices.interrupted();var first=PlsSem.fit(data,blocks,edges,options);if(!first.converged())throw new IllegalArgumentException("The first-stage PLS model did not converge.");double[][] scores=first.scores();if(referenceOne!=null){double[] signs=Bootstrap.alignment(scores,referenceOne,rows);for(var row:scores)for(int j=0;j<signs.length;j++)row[j]*=signs[j];}
        double[][] augmented=augment(data,scores);var second=PlsSem.fit(augmented,prepared.blocks,specification.edges,specification.options);if(!second.converged())throw new IllegalArgumentException("The higher-order second-stage model did not converge.");double[] signs=referenceTwo==null?new double[prepared.blocks.size()]:Bootstrap.alignment(second.scores(),referenceTwo,rows);if(referenceTwo==null)Arrays.fill(signs,1);double[][] weights=second.weights(),loadings=second.loadings();List<DimensionResult> dimensions=new ArrayList<>();
        for(int index=0;index<specification.higherOrder.size();index++){var dimension=specification.higherOrder.get(index);int block=specification.retained.length+index;for(int j=0;j<dimension.lowerOrder.length;j++)dimensions.add(new DimensionResult(block,dimension.name,dimension.lowerOrder[j],blocks.get(dimension.lowerOrder[j]).name(),dimension.mode,dimension.measurementType,weights[block][j]*signs[block],loadings[block][j]*signs[block]));}
        List<SpecificIndirect> indirect=new ArrayList<>();double[][] paths=second.pathCoefficients();for(var route:prepared.routes){double value=1;for(int j=1;j<route.size();j++){int source=route.get(j-1),target=route.get(j);value*=paths[source][target]*signs[source]*signs[target];}indirect.add(new SpecificIndirect(route.getFirst(),route.getLast(),route,value));}
        double[] base=Bootstrap.values(second,prepared.blocks,prepared.parameters,signs);List<Effect> effects=new ArrayList<>();for(int index=0;index<prepared.parameters.size();index++){var parameter=prepared.parameters.get(index);if(parameter.column()<0)effects.add(new Effect(parameter.family(),parameter.source(),parameter.target(),base[index]));}
        Fit result=new Fit(specification,options,data.length,data[0].length,blocks,edges,prepared.blocks,first,second,dimensions,effects,indirect,prepared.warnings);return new State(result,base,augmented);
    }
    public static Fit fit(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Specification specification){int width=Matrices.width(data,3);Prepared prepared=prepare(width,blocks,edges,specification);return compute(data,List.copyOf(blocks),List.copyOf(edges),options,specification,prepared,null,null,null).result;}
    record PipelineStep(Fit fit,double[][] nextInput,List<Bootstrap.Parameter> parameters,double[] estimates){}
    static PipelineStep pipelineStep(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Specification specification,Fit reference,int[] rows){var prepared=prepare(Matrices.width(data,3),blocks,edges,specification);var state=compute(data,blocks,edges,options,specification,prepared,reference==null?null:reference.firstStage().scores(),reference==null?null:reference.secondStage().scores(),rows);List<Bootstrap.Parameter> parameters=new ArrayList<>(prepared.parameters);for(var effect:state.result.specificIndirect())parameters.add(new Bootstrap.Parameter("Specific indirect effect",effect.source(),effect.target(),-1,String.join(" → ",effect.route().stream().map(index->prepared.blocks.get(index).name()).toList())));double[] baseValues=values(state);List<Double> additional=new ArrayList<>();for(int j=0;j<state.result.secondStage().rSquared().length;j++)if(Double.isFinite(state.result.secondStage().rSquared()[j])){parameters.add(new Bootstrap.Parameter("R squared",j,j,-1,prepared.blocks.get(j).name()));additional.add(state.result.secondStage().rSquared()[j]);}double[] combined=Arrays.copyOf(baseValues,baseValues.length+additional.size());for(int j=0;j<additional.size();j++)combined[baseValues.length+j]=additional.get(j);return new PipelineStep(state.result,state.augmented,List.copyOf(parameters),combined);}
    private static double[] values(State state){Fit fit=state.result;double[] result=Arrays.copyOf(state.base,state.base.length+fit.specificIndirect.size());for(int j=0;j<fit.specificIndirect.size();j++)result[state.base.length+j]=fit.specificIndirect.get(j).value;return result;}

    public static Resampled bootstrap(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Specification specification,Bootstrap.Options resampling,IntConsumer progress){int width=Matrices.width(data,3);Prepared prepared=prepare(width,blocks,edges,specification);State originalState=compute(data,blocks,edges,options,specification,prepared,null,null,null);Fit point=originalState.result;double[][] referenceOne=point.firstStage.scores(),referenceTwo=point.secondStage.scores();var base=prepared.parameters;List<Bootstrap.Parameter> parameters=new ArrayList<>(base);for(var effect:point.specificIndirect)parameters.add(new Bootstrap.Parameter("Specific indirect effect",effect.source,effect.target,-1,String.join(" → ",effect.route.stream().map(index->prepared.blocks.get(index).name()).toList())));double[] original=values(originalState);
        var inference=Resampling.run(data,parameters,original,resampling,(sample,rows)->{var result=compute(sample,blocks,edges,options,specification,prepared,referenceOne,referenceTwo,rows);return values(result);},progress,"Explicit two-stage higher-order PLS","Each bootstrap/jackknife refits first-stage scores, aligns their signs before augmentation, refits second-stage PLS, then aligns second-stage scores/weights/loadings and paths to the original sampled rows.");List<String> warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference);
    }
}
